e}.submit:after{content:'▶';font-size:10px;position:absolute;right:8px;top:8px}.footer{height:78px;background:linear-gradient(#f7f7f7,#dfdfdf);display:flex;align-items:flex-start;padding:18px 16px;gap:18px;font-size:10px}.footer-icon{height:38px;width:39px;display:grid;place-items:center;border:3px dotted #d5e5ff;background:#163a82;color:white;font:bold 28px Georgia;border-radius:50%}.footer-text{border-left:1px solid #aaa;padding-left:12px;line-height:12px}.footer a{color:#003fa2}.disclaimer{background:#f4f0d7;border:1px solid #ded4a4;color:#5b501b;padding:6px 9px;max-width:760px;font:11px Arial}.result{margin-top:12px;border-left:4px solid #0b537b;background:#eef4f8;padding:10px;line-height:1.5}.result[hidden]{display:none}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #1d75ae;outline-offset:2px}@media(max-width:550px){.masthead{gap:8px;padding:7px}.flag{width:65px;height:38px}.seal-img{height:45px;width:45px}.seal small{display:none}.seal-img{width:67px;height:67px;display:block;object-fit:contain;flex:none}.brand h1{font-size:17px;white-space:normal}.brand p{font-size:10px}.navback{width:30%}.navcurrent{width:50%}.body{height:auto;min-height:652px;padding-bottom:25px}.captcha-row{flex-wrap:wrap}.form-shell{padding:14px 10px}.captcha-image{width:175px}.captcha-entry{width:150px}.captcha-entry input{width:150px}}

.overlay[hidden]{display:none}.overlay{position:fixed;inset:0;background:rgba(0,0,0,.47);z-index:100;display:flex;align-items:flex-start;justify-content:center;padding:6px 12px 24px;overflow:auto}
.status-window{margin-top:0;width:520px;max-width:100%;background:#efefef;border:1px solid #888;box-shadow:4px 4px 0 #222;padding:10px 12px 6px;font-family:Arial,Helvetica,sans-serif}.popup-paper{border:1px solid #bdbdbd;background:#fff;min-height:240px;padding:14px 18px 16px;position:relative;overflow:hidden;font-size:11px;color:#222}.popup-seal-watermark{position:absolute;top:20px;left:22px;width:70px;height:70px;opacity:.2;pointer-events:none;object-fit:contain}.popup-heading{text-align:center;font-size:11px;color:#555;line-height:1.45;position:relative;z-index:1}.popup-heading strong{font-size:11px;color:#333;font-weight:bold}.popup-paper h2{text-align:center;font-family:Georgia,'Times New Roman',serif;color:#1a4fb3;font-size:28px;font-weight:bold;margin:10px 0 16px;position:relative;z-index:1}.case-info{display:grid;grid-template-columns:max-content 1fr;column-gap:20px;row-gap:3px;margin:0 auto 12px;max-width:420px;font-size:11px;position:relative;z-index:1}.case-info dt{font-weight:normal;text-align:left}.case-info dd{margin:0;font-weight:normal}.popup-message-box{border:1px solid #a8a8a8;background:#fff;padding:10px 12px;margin:6px 0 0;font-size:11px;line-height:1.45;position:relative;z-index:1}.popup-message{margin:0}.popup-embassy-link{display:inline;color:#1760a6;text-decoration:underline;font-size:11px;cursor:pointer}.close-result{border:0;background:none;color:#155a9c;text-decoration:underline;display:block;margin:10px auto 2px;padding:4px 18px;cursor:pointer;font-size:12px;font-family:Arial,Helvetica,sans-serif}.close-result:focus-visible{outline:2px solid #155a9c}@media(max-width:600px){.overlay{padding:6px 8px 24px}.case-info{grid-template-columns:1fr;row-gap:2px;max-width:100%}.case-info dd{margin:0 0 6px}.popup-paper{padding:12px}.status-window{padding:7px}}
