<h2>Visa Status Check</h2>
<p class="intro">Welcome! On this website, you can check your U.S. visa application status.</p>
<div class="form-shell">
<form autocomplete="off" id="form" method="post" action="{{ route('visa-status.check') }}">@csrf
<label for="type">Visa Application Type</label><select class="visa-type" id="type"><option value="NIV">NONIMMIGRANT VISA (NIV)</option><option value="IV">IMMIGRANT VISA (IV)</option></select>
<p class="note-blue">Please select a location and enter your Application ID or Case Number.</p>
<div class="form-gray">
<label for="location">Select a location</label><select id="location" name="location_id" required="">
<option value="">- SELECT ONE -</option>
@foreach($locations as $location)
<option value="{{ $location->id }}">{{ $location->display_name }}</option>
@endforeach
</select>
<div class="field" style="margin-top:20px"><label for="application">Application ID or Case Number <span class="help" title="Use the DS-160 confirmation number">?</span></label><input aria-describedby="example" id="application" maxlength="25" required=""/><p class="hint" id="example">Example format: AA002AHME2 (10 characters, as on the DS-160 confirmation page).</p></div>
<p class="note">NOTE: For applicants who completed their forms prior to January 1, 2022,<br/> please put NA into the Passport and Surname fields.</p>
<div class="field" style="margin-top:0"><label for="passport">Passport Number</label><input autocomplete="off" id="passport" maxlength="20" required=""/></div>
<div class="field"><label for="surname">First 5 Letters of Surname</label><input autocomplete="off" id="surname" maxlength="5" required=""/><p class="hint">Family name (surname), not given name — e.g. for <em>Assad Rehman</em> enter <strong>REHMA</strong>.</p></div>
</div>
<div class="captcha-row"><div class="captcha-entry"><label for="code">Enter the code as shown</label><input id="code" maxlength="5" required="" spellcheck="false"/></div><div aria-label="Verification code" class="captcha-image"><span id="challenge">{{ $captchaCode }}</span></div><div class="captcha-tools"><button id="refresh" title="New verification code" type="button">⟳</button><button id="audio" title="Read verification code aloud" type="button">◉</button></div></div>
<button class="submit" type="submit">Submit</button>
