<div class="overlay" hidden="" id="modal-overlay"><div aria-labelledby="popup-status" aria-modal="true" class="status-window" role="dialog" tabindex="-1"><div class="popup-paper"><div class="popup-heading">Visa Application Status<br/><strong id="popup-visa-type-line">NONIMMIGRANT VISA APPLICATION</strong></div><h2 id="popup-status">Approved</h2><dl class="case-info"><dt>Application ID or Case Number:</dt><dd id="popup-app"></dd><dt>Case Created:</dt><dd id="popup-created"></dd><dt>Case Last Updated:</dt><dd id="popup-updated"></dd></dl><div class="popup-message-box"><p class="popup-message" id="popup-message"></p><span class="popup-embassy-link" hidden="" id="popup-embassy" role="link" tabindex="0"></span></div></div><button class="close-result" id="close-result" type="button">Close</button></div></div><script>(()=>{
const refreshUrl=@json(route('visa-status.captcha'));
const checkUrl=@json(route('visa-status.check'));
const csrfToken=document.querySelector('meta[name="csrf-token"]')?.content||document.querySelector('input[name="_token"]')?.value;
const defaultType=@json($defaultType);
const $=id=>document.getElementById(id);
const modal=$('modal-overlay'),dialog=document.querySelector('.status-window');let priorFocus=null;
function error(msg){$('result').hidden=false;$('result').textContent=msg;}
function clearError(){$('result').hidden=true;$('result').textContent='';}
const paper=document.querySelector('.popup-paper');const mastheadSeal=document.querySelector('.masthead .seal-img');if(paper&&mastheadSeal&&!paper.querySelector('.popup-seal-watermark')){const wm=mastheadSeal.cloneNode(true);wm.className='popup-seal-watermark';wm.alt='';wm.setAttribute('aria-hidden','true');paper.prepend(wm);}
function showPopup(data){priorFocus=document.activeElement;$('popup-status').textContent=data.status;$('popup-app').textContent=data.confirmation_number;$('popup-created').textContent=data.created;$('popup-updated').textContent=data.updated;$('popup-message').textContent=data.message||'';const embassy=$('popup-embassy');if(data.embassy_link){embassy.textContent=data.embassy_link;embassy.hidden=false;}else{embassy.hidden=true;embassy.textContent='';}$('popup-visa-type-line').textContent=$('type').value==='IV'?'IMMIGRANT VISA APPLICATION':'NONIMMIGRANT VISA APPLICATION';modal.hidden=false;dialog.focus();}
function close(){modal.hidden=true;if(priorFocus&&priorFocus.focus)priorFocus.focus();}
$('close-result').addEventListener('click',close);
modal.addEventListener('click',e=>{if(e.target===modal)close();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)close();});
async function refreshCaptcha(){const res=await fetch(refreshUrl,{headers:{'Accept':'application/json'}});if(!res.ok)return;const data=await res.json();$('challenge').textContent=data.code;$('code').value='';clearError();}
$('refresh').addEventListener('click',()=>{refreshCaptcha();});
$('audio').addEventListener('click',()=>{const code=$('challenge').textContent;if('speechSynthesis' in window){const u=new SpeechSynthesisUtterance(code.split('').join(' '));u.rate=.65;speechSynthesis.speak(u);}else alert('Verification code: '+code);});
$('form').addEventListener('submit',async e=>{e.preventDefault();clearError();if(!$('location').value){error('Please select a location.');return;}const payload={visa_type:$('type').value,location_id:$('location').value,confirmation_number:$('application').value.trim(),passport_number:$('passport').value.trim(),surname:$('surname').value.trim(),captcha:$('code').value.trim(),_token:csrfToken};
const res=await fetch(checkUrl,{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrfToken,'X-Requested-With':'XMLHttpRequest'},body:JSON.stringify(payload)});
const data=await res.json().catch(()=>({}));if(!res.ok){error(data.message||'The information you entered does not match our records.');if(res.status===422){await refreshCaptcha();}return;}showPopup(data.popup);});
if(defaultType==='IV')$('type').value='IV';
const params=new URLSearchParams(location.search);
if(params.get('cn'))$('application').value=params.get('cn');
if(params.get('location_id'))$('location').value=params.get('location_id');
if(params.get('passport'))$('passport').value=params.get('passport');
if(params.get('surname'))$('surname').value=params.get('surname');
})();
</script></body></html>
